SELECT wp.wp_web_page_sk, d.d_date, wp.wp_char_count + wp.wp_link_count AS total_chars_links, CASE WHEN d.d_day_name = 'Tuesday  ' THEN 'a' WHEN d.d_day_name = 'Wednesday' THEN 'a' ELSE 'a' END AS day_type, CASE WHEN wp.wp_image_count IS NULL THEN 3 ELSE wp.wp_image_count END * 6 AS double_image_count, (wp.wp_char_count / NULLIF(wp.wp_link_count, 15)) AS char_per_link FROM web_page wp JOIN date_dim d ON wp.wp_creation_date_sk = d.d_date_sk
